def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_m, last_o = history[-1]

    opp_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_streak += 1
        i -= 1

    opp_d_total = 0
    my_d_total = 0
    for m, o in history:
        if m == 'D':
            my_d_total += 1
        if o == 'D':
            opp_d_total += 1

    r10 = history[-10:] if n >= 10 else history
    r20 = history[-20:] if n >= 20 else history
    len10 = len(r10)
    len20 = len(r20)

    opp_c10 = sum(1 for _, o in r10 if o == 'C')
    opp_c20 = sum(1 for _, o in r20 if o == 'C')

    failed = 0
    resp_c = 0
    resp_d = 0
    copy = 0
    total = 0

    start = n - len20
    for idx in range(start + 1, n):
        prev_m, _ = history[idx - 1]
        m, o = history[idx]

        if prev_m == 'D':
            if o == 'C':
                resp_c += 1
            else:
                resp_d += 1

        total += 1
        if o == prev_m:
            copy += 1

        if m == 'C' and prev_m == 'D' and o == 'D':
            failed += 1

    copy_rate = float(copy) / float(total) if total > 0 else 1.0

    if last_o == 'D':
        if last_m == 'C' and n >= 2 and failed < 3 and opp_c10 > 0:
            pm, po = history[-2]
            if pm == 'D' and po == 'D':
                return 'C'

        if last_m == 'C':
            if opp_streak <= 4:
                if opp_d_total * 100 > n * 45 and opp_c10 * 100 < len10 * 45:
                    return 'D'
                return 'C'
            return 'D'

        if opp_c10 > 0 and failed < 3:
            return 'C'
        if opp_c20 >= 4 and failed < 4 and opp_d_total * 100 <= n * 65:
            return 'C'
        return 'D'

    if last_m == 'D':
        if resp_c >= 2 and resp_d <= max(1, resp_c // 2) and opp_c10 * 10 >= len10 * 5:
            return 'D'
        if n >= 88 and resp_c >= 1 and resp_d == 0:
            return 'D'
        return 'C'

    if n >= 18 and opp_c10 * 10 >= len10 * 5 and copy_rate < 0.72:
        if opp_d_total * 100 <= n * 35 and resp_d <= max(2, resp_c // 2 + 1):
            if resp_c >= 2:
                return 'D'
            if rng.random() < 0.15:
                return 'D'

    if n >= 80 and opp_d_total == 0 and rng.random() < 0.02:
        return 'D'

    return 'C'
